// Получено: 1
// Получено: 2
// Получено: 3
// Получено: 4
}

void main() async {
// Создаём контроллер
final controller = StreamController<String>();

// Слушаем Stream
controller.stream.listen((event) {
print('Получено: $event');
});

// Добавляем события
controller.add('Привет');
controller.add('Мир');

// Закрываем контроллер
await controller.close();
}

