import 'dart:async';

class CounterBloc {
// StreamController для событий
final _eventController = StreamController<CounterEvent>();
Stream<CounterEvent> get events => _eventController.stream;

// StreamController для состояний
final _stateController = StreamController<CounterState>();
Stream<CounterState> get states => _stateController.stream;

// Текущее состояние
int _count = 0;

// Обработка событий
void processEvents() {
events.listen((event) {
if (event is IncrementEvent) {
_count++;
_stateController.add(CountState(_count));
} else if (event is DecrementEvent) {
_count--;
_stateController.add(CountState(_count));
}
});
}

// Методы для добавления событий
void addEvent(CounterEvent event) {
_eventController.add(event);
}

// Очистка ресурсов
void dispose() {
_eventController.close();
_stateController.close();
}
}

// События
abstract class CounterEvent {}
class IncrementEvent extends CounterEvent {}
class DecrementEvent extends CounterEvent {}

// Состояния
class CountState {
final int count;
CountState(this.count);
}

import 'package:bloc/bloc.dart';

// События
abstract class TodoEvent {}
class TodoAdded extends TodoEvent {
final String title;
TodoAdded(this.title);
}

// Состояния
abstract class TodoState {}
class TodoInitial extends TodoState {}
class TodoHasItems extends TodoState {
final List<String> items;
TodoHasItems(this.items);
}

// BLoC на основе Stream
class TodoBloc extends Bloc<TodoEvent, TodoState> {
TodoBloc() : super(TodoInitial()) {
on<TodoAdded>(_onTodoAdded);
}

void _onTodoAdded(TodoAdded event, Emitter<TodoState> emit) {
// Логика обработки
emit(TodoHasItems(['Новая задача']));
}
}

void main() {
final controller = StreamController<int>();

controller.stream
.map((value) => value * 2)
.listen((result) => print('Удвоено: $result'));

controller.add(5);   // Удвоено: 10
controller.add(10);  // Удвоено: 20
}

void main() {
final controller = StreamController<int>();

controller.stream
.where((value) => value.isEven)
.listen((result) => print('Чётное: $result'));

controller.add(1);   // Не выводится
controller.add(2);   // Чётное: 2
controller.add(3);   // Не выводится
controller.add(4);   // Чётное: 4
}

void main() {
final controller = StreamController<String>();

controller.stream
.switchMap((query) {
return Stream.fromFuture(
fetchResults(query),
);
})
.listen((results) => print('Результаты: $results'));

controller.add('Flutter');
controller.add('Dart');
}

Future<List<String>> fetchResults(String query) async {
await Future.delayed(const Duration(seconds: 1));
return ['Результат 1 для $query', 'Результат 2 для $query'];
}

