final stream2 = StreamController<String>();

Rx.combineLatest2<int, String, String>(
stream1.stream,
stream2.stream,
(number, text) => '$text: $number',
).listen((result) => print(result));

stream1.add(1);
stream2.add('Привет'); // Вывод: Привет: 1
}

import 'dart:async';
import 'package:flutter/material.dart';

class SearchBloc {
final _searchController = StreamController<String>();
Timer? _debounceTimer;

Stream<String> get _searchStream => _searchController.stream;

// Debounce — задержка перед выполнением
Stream<String> get searchResults async* {
await for (final query in _searchStream) {
_debounceTimer?.cancel();
_debounceTimer = Timer(const Duration(milliseconds: 300), () {
if (query.isNotEmpty) {
// Выполняем поиск
_performSearch(query);
}
});
}
}

void _performSearch(String query) {
// Логика поиска
print('Поиск: $query');
}

void onSearchChanged(String query) {
_searchController.add(query);
}

void dispose() {
_searchController.close();
_debounceTimer?.cancel();
}
}

// Использование в UI
class SearchPage extends StatelessWidget {
final SearchBloc _searchBloc = SearchBloc();

@override
Widget build(BuildContext context) {
return Scaffold(
appBar: AppBar(title: const Text('Поиск')),
body: Column(
children: [
TextField(
onChanged: _searchBloc.onSearchChanged,
decoration: const InputDecoration(
hintText: 'Введите запрос...',
prefixIcon: Icon(Icons.search),
),
),
const Expanded(child: SearchResults()),
],
),
);
}
}
